INSERT INTO `agendas` (`id`, `title`, `slug`, `content`, `location`, `event_date`, `status`, `featured_image`, `created_at`, `updated_at`) VALUES
(57, 'Haflah Ikhtitam & Wisuda Akbar Santri Pondok Pesantren Raudhatul Ulum', 'haflah-ikhtitam-wisuda-akbar-santri-ppru', '<p>Pelepasan resmi dan wisuda akbar santri akhir KMI, Madrasah Aliyah, SMA Islam Terpadu, dan wisuda sarjana Institut Agama Islam Nur Raudhatul Ulum Sakatiga. Menampilkan parade bahasa, atraksi tapak suci, dan orasi ilmiah alumni terkemuka.</p>', 'Auditorium Utama & Lapangan Hijau pondok PPRU Sakatiga', '2026-05-18 01:00:00', 'publish', '/uploads/ppru-wisuda-akbar.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(58, 'Lomba Perkemahan Prestasi Penggalang & Penegak (LP3) Nasional Ke-28', 'lp3-lomba-perkemahan-prestasi-santri-ppru', '<p>Ajang perkemahan kepanduan santri terbesar se-Sumatera yang mempertemukan ratusan pangkalan pondok pesantren dalam berbagai perlombaan pionering, semaphore, tata laksana tenda, dan ketangkasan alam terbuka.</p>', 'Bumi Perkemahan Raudhatul Ulum Sakatiga', '2026-07-22 00:30:00', 'publish', '/uploads/ppru-pramuka.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(59, 'Dauroh Tahfidz Al-Qur\'an 30 Juz & Pengambilan Sanad Bersama Masyaikh', 'dauroh-tahfidz-quran-30-juz-sanad-ppru', '<p>Program karantina tahfidz intensif santri Madrasah Tahfizhul Qur\'an Al-Aulad (MTQ) dengan bimbingan langsung para huffadz mutqin dan penguji bersanad internasional dari Kairo Mesir dan Madinah.</p>', 'Masjid Jami\' & Asrama Tahfidz Putra-Putri PPRU', '2026-04-09 22:00:00', 'publish', '/uploads/ppru-halaqah-quran.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(60, 'Ujian Tahriri & Syafahi Semester Genap Tahun Ajaran 2026/2027', 'ujian-tahriri-syafahi-semester-genap-ppru', '<p>Pelaksanaan evaluasi pembelajaran pondok pesantren melalui ujian lisan (syafahi) bahasa Arab, bahasa Inggris, fiqih, tafsir, dan tauhid dilanjutkan ujian tertulis (tahriri) kurikulum Kemenag dan Kemendikdasmen.</p>', 'Gedung Kelas Terpadu Raudhatul Ulum', '2026-06-02 00:00:00', 'publish', '/uploads/ppru-gedung-utama.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(61, 'Musabaqah Tilawatil Qur\'an & Hadits (MQK/MTQ) Antar Pondok Pesantren', 'musabaqah-tilawatil-quran-dan-kitab-kuning-ppru', '<p>Perlombaan membaca kitab kuning (Musabaqah Qira\'atil Kutub), tilawah Qur\'an, kaligrafi Islam, dan cerdas cermat keislaman untuk mengasah keilmuan dan ketajaman berpikir generasi muda santri.</p>', 'Kompleks Institut & Aula Al-Azhar PPRU', '2026-08-14 01:30:00', 'publish', '/uploads/ppru-mtq.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(62, 'Kajian Akbar Bulanan & Silaturahmi Wali Santri Seluruh Indonesia', 'kajian-akbar-dan-silaturahmi-wali-santri-ppru', '<p>Majelis taujih wal irsyad bersama Mudir Pondok Pesantren Raudhatul Ulum dan Dewan Asatidz, sarana sinergi orang tua dan pondok dalam membina karakter santri muttaqien, mandiri, dan berwawasan global.</p>', 'Masjid Jami\' Raudhatul Ulum Sakatiga', '2026-09-06 02:00:00', 'publish', '/uploads/ppru-masjid-agung.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(63, 'Olimpiade Robotika, Coding, & Sains Teknologi Santri Nusantara', 'olimpiade-robotika-coding-sains-santri-ppru', '<p>Kompetisi inovasi teknologi robotika mikrokontroler, pemrograman kecerdasan buatan, dan karya ilmiah remaja santri madrasah terpadu untuk menyongsong Indonesia Emas 2045.</p>', 'Laboratorium Komputer CBT & Ruang Riset Sains PPRU', '2026-10-15 01:00:00', 'publish', '/uploads/ppru-robotika-sains.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(64, 'Dauroh Bahasa Arab & Rihlah Ilmiah Muadalah Bersama Delegasi Al-Azhar', 'dauroh-bahasa-arab-dan-muadalah-al-azhar-ppru', '<p>Penguatan lisaniyah muhadatsah yaumiyyah dan pembekalan seleksi studi lanjut beasiswa Universitas Al-Azhar Kairo bersama dosen tamu dan perwakilan lembaga muadalah internasional.</p>', 'Pusat Bahasa & Perpustakaan Islam PPRU', '2026-11-20 01:30:00', 'publish', '/uploads/ppru-alazhar.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(65, 'Kejuaraan Olahraga Santri & Festival Seni Silat Tradisional Tapak Suci', 'kejuaraan-olahraga-dan-seni-santri-ppru', '<p>Pekan olahraga dan seni santri mempertandingkan panahan sunnah, sepak bola mini, bulu tangkis, bola voli, marawis, hadroh, serta kejuaraan bela diri antar konsulat santri daerah.</p>', 'Gelanggang Olahraga & Lapangan Hijau PPRU', '2026-12-10 07:00:00', 'publish', '/uploads/ppru-pencak-silat.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(66, 'Sosialisasi & Tes Pemetaan Bakat Minat Santri Baru T.A. 2027/2028', 'tes-pemetaan-bakat-minat-santri-baru-ppru', '<p>Pelaksanaan asesmen diagnostik akademik, tes kemampuan baca tulis Al-Qur\'an, dan wawancara komitmen santri serta wali santri calon generasi muttaqien Raudhatul Ulum.</p>', 'pondok Terpadu Pondok Pesantren Raudhatul Ulum Sakatiga', '2027-01-25 01:00:00', 'publish', '/uploads/ppru-panahan-santri.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(67, 'Wisuda Akbar Tahfidz Al-Qur\'an 30 Juz & Khotmil Kutub Angkatan 2026', 'wisuda-akbar-tahfidz-al-quran-30-juz-khotmil-kutub-angkatan-2026', 'Prosesi wisuda akbar hafalan Al-Qur\'an 30 juz mutqin santri kelas akhir serta penganugerahan ijazah sanad tahfidz bersama pimpinan pesantren.', 'Gedung Pertemuan Serbaguna Kampus A PPRU Sakatiga', '2026-10-04 06:30:00', 'upcoming', '/uploads/official/drone-raudhatul-ulum.webp', '2026-09-20 16:12:41', '2026-09-20 16:12:41'),
(68, 'Ujian Penilaian Akhir Semester (PAS) Terpadu & Standar Muadalah Al-Azhar', 'ujian-penilaian-akhir-semester-pas-terpadu-standar-muadalah-al-azhar', 'Pelaksanaan evaluasi pembelajaran semester genap berbasis Computer Based Test (CBT) dan ujian lisan bahasa Arab-Inggris.', 'Ruang Kelas & Laboratorium Komputer Seluruh Unit', '2026-10-18 05:30:00', 'upcoming', '/uploads/official/kbm-santri-0054.webp', '2026-09-20 16:12:41', '2026-09-20 16:12:41'),
(69, 'Pekan Olahraga, Seni & Bahasa Santri (PORSENI) Antar-Asrama Se-Pesantren', 'pekan-olahraga-seni-bahasa-santri-porseni-antar-asrama-se-pesantren', 'Ajang unjuk ketangkasan olahraga memanah, futsal, tapak suci, orasi bahasa Arab-Inggris, dan festival kreasi seni santri.', 'Kompleks Lapangan Olahraga Terpadu Kampus B', '2026-11-01 07:00:00', 'upcoming', '/uploads/official/panahan-santri.webp', '2026-09-20 16:12:41', '2026-09-20 16:12:41'),
(70, 'Sarasehan & Temu Akbar Silaturahmi Wali Santri Nasional PPRU Sakatiga', 'sarasehan-temu-akbar-silaturahmi-wali-santri-nasional-ppru-sakatiga', 'Forum tahunan komunikasi antara Mudir, dewan asatidz, dan seluruh wali santri guna mengevaluasi tumbuh kembang anak didik.', 'Masjid Jami\' Pondok Pesantren Raudhatul Ulum', '2026-11-15 08:00:00', 'upcoming', '/uploads/official/ngaji-sore.webp', '2026-09-20 16:12:41', '2026-09-20 16:12:41');
