INSERT INTO `dewan_asatidz` (`id`, `unit_pendidikan_id`, `name`, `slug`, `position`, `fraction`, `profile_summary`, `education`, `photo`, `order`, `created_at`, `updated_at`) VALUES
(271, NULL, 'KH. Tol\'at Wafa Ahmad, Lc.', 'kh-tolat-wafa-ahmad-lc', 'Mudir Pondok Pesantren Raudhatul Ulum', 'Pimpinan Pesantren', 'Pimpinan & Pengasuh Utama Pondok Pesantren Raudhatul Ulum Sakatiga. Alumni Universitas Al-Azhar Kairo Mesir, pembina ribuan santri dan hafizh Qur\'an di seluruh pelosok nusantara.', 'S1 Syari\'ah Islamiyah - Universitas Al-Azhar Kairo, Mesir', '/uploads/kh-tolat-wafa-ahmad.webp', 1, '2026-09-20 16:25:12', '2026-09-20 16:25:12'),
(272, NULL, 'Drs. KH. Karim Kasim', 'drs-kh-karim-kasim', 'Ketua Dewan Pembina YAPIRUS', 'Yayasan', '<p>Ketua Dewan Pembina Yayasan Perguruan Islam Raudhatul Ulum Sakatiga (YAPIRUS). Dedikasi lebih dari 40 tahun dalam pembinaan akhlak, tarbiyah santri, dan pengembangan institusi pendidikan Islam terpadu.</p>', 'Sarjana Pendidikan Islam & Tarbiyah', '/uploads/dewan/default-avatar-1789930295-n9exv.webp', 2, '2026-09-20 16:25:12', '2026-09-20 16:51:35'),
(273, NULL, 'Ustadz H. Faisal Abdullah, S.T.', 'ustadz-h-faisal-abdullah-st', 'Direktur Sarana, Prasarana & Keuangan', 'Yayasan', '<p>Mengawal modernisasi tata kelola sarana prasarana, laboratorium sains, kampus asrama terpadu, dan ekosistem digital Pondok Pesantren Raudhatul Ulum Sakatiga.</p>', 'S1 Teknik Sipil & Manajemen Infrastruktur', '/uploads/dewan/default-avatar-1789930307-Duhv1.webp', 3, '2026-09-20 16:25:12', '2026-09-20 16:51:47'),
(274, NULL, 'Ustadz H. Ahmad Dailami, S.Pd.I.', 'ustadz-h-ahmad-dailami-spdi', 'Kepala Madrasah Aliyah Raudhatul Ulum (MARU)', 'Pendidik', '<p>Memimpin jenjang Madrasah Aliyah dengan kurikulum muadalah Al-Azhar Kairo dan Kemenag. Sukses menghantarkan puluhan alumni meraih beasiswa ke Timur Tengah dan PTN ternama.</p>', 'S1 Pendidikan Agama Islam & Ma\'had Aly', '/uploads/dewan/default-avatar-1789930318-7WpSJ.webp', 4, '2026-09-20 16:25:12', '2026-09-20 16:51:58'),
(275, NULL, 'Ustadz Agi Gustiawan, S.Pd.', 'ustadz-agi-gustiawan-spd', 'Kepala SMA Islam Terpadu Raudhatul Ulum', 'Pendidik', '<p>Kepala SMAIT Raudhatul Ulum. Berkomitmen memadukan kurikulum sains nasional, pembinaan karakter Islami, dan riset ilmiah remaja berprestasi hingga kancah olimpiade sains.</p>', 'S1 Pendidikan Sains & Matematika', '/uploads/dewan/default-avatar-1789930331-md7GF.webp', 5, '2026-09-20 16:25:12', '2026-09-20 16:52:11'),
(276, NULL, 'Ustadz Muhammad Syakir, M.Pd.', 'ustadz-muhammad-syakir-mpd', 'Kepala MTs Raudhatul Ulum (MATSARU)', 'Pendidik', '<p>Kepala Madrasah Tsanawiyah Raudhatul Ulum. Berpengalaman dalam penguatan bahasa Arab-Inggris harian santri, tahsin bersanad, dan kedisiplinan asrama 24 jam.</p>', 'S2 Manajemen Pendidikan Islam', '/uploads/dewan/default-avatar-1789930345-j6es9.webp', 6, '2026-09-20 16:25:12', '2026-09-20 16:52:25'),
(277, NULL, 'Ustadzah Hj. Fatimah Azzahra, Lc., M.Ag.', 'ustadzah-hj-fatimah-azzahra-lc-mag', 'Kepala Bagian Tahfidz & Pengasuhan Putri', 'Pendidik', '<p>Alumni Universitas Al-Azhar Kairo dan Pengasuh Markaz Tahfidz Putri PPRU. Telah mencetak puluhan santriwati mutqin 30 juz berakhlak Qur\'ani dan berjiwa da\'iyah.</p>', 'S1 Ushuluddin Al-Azhar Mesir, S2 Studi Islam', '/uploads/dewan/default-avatar-1789930357-pGEJk.webp', 7, '2026-09-20 16:25:12', '2026-09-20 16:52:37'),
(278, NULL, 'Ustadz M. Rasyid Ridho, S.Th.I.', 'ustadz-m-rasyid-ridho-sthi', 'Kepala Pengasuhan & Kedisiplinan Santri Putra', 'Pendidik', '<p>Kepala Biro Pengasuhan Santri Putra (BPSP). Mengawal penegakan sunnah pondok, kepanduan, olahraga bela diri, dan penempaan mental kepemimpinan santri.</p>', 'S1 Tafsir Hadits & Ilmu Al-Qur\'an', '/uploads/dewan/default-avatar-1789930372-FRWiG.webp', 8, '2026-09-20 16:25:12', '2026-09-20 16:52:52'),
(279, 1, 'Ustadz H. Abdul Halim, Lc.', 'ustadz-h-abdul-halim-lc-unit-1', 'Kepala / Mudir Madrasah Aliyah Raudhatul Ulum', 'MARU', 'Tenaga pendidik profesional dan berdedikasi tinggi di lingkungan Madrasah Aliyah Raudhatul Ulum Pondok Pesantren Raudhatul Ulum Sakatiga.', 'S2 Manajemen Pendidikan Islam & Ma\'had Aly', '/uploads/avatar-neutral-gray.svg', 1, '2026-09-20 16:26:00', '2026-09-20 16:26:00'),
(280, 1, 'Ustadz M. Syakir, M.Pd. (MARU)', 'ustadz-m-syakir-mpd-maru-unit-1', 'Wakil Kepala Bidang Kurikulum & Pengajaran MARU', 'MARU', 'Tenaga pendidik profesional dan berdedikasi tinggi di lingkungan Madrasah Aliyah Raudhatul Ulum Pondok Pesantren Raudhatul Ulum Sakatiga.', 'S2 Manajemen Kurikulum Pendidikan', '/uploads/avatar-neutral-gray.svg', 2, '2026-09-20 16:26:00', '2026-09-20 16:26:00'),
