INSERT INTO `pages` (`id`, `title`, `slug`, `excerpt`, `content`, `image`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES
(1, 'Sambutan Mudir Pondok Pesantren Raudhatul Ulum', 'sambutan-kepala-sekolah', NULL, '<h2>Assalamu\'alaikum Warahmatullahi Wabarakatuh</h2><p>Segala puji dan syukur kita panjatkan ke hadirat Allah Subhanahu wa Ta\'ala, yang telah melimpahkan rahmat, taufiq, dan inayah-Nya kepada kita semua. Shalawat dan salam senantiasa tercurahkan kepada junjungan kita Nabi Besar Muhammad Shallallahu \'Alaihi Wasallam, keluarga, sahabat, dan pengikutnya yang setia hingga akhir zaman.</p><p>Pondok Pesantren Raudhatul Ulum Sakatiga sejak didirikannya pada tanggal 1 Agustus 1950, bertekad menjadi benteng pertahanan aqidah umat dan basis kaderisasi generasi terbaik (Khoiru Ummah). Memadukan kurikulum kepesantrenan terpadu (Pondok Modern Gontor), Kementerian Agama, serta kurikulum nasional, santri dibina selama 24 jam dalam lingkungan asrama yang asri, disiplin, dan islami.</p><p>Kami menyambut hangat para orang tua/wali santri dan masyarakat luas yang ingin bermitra bersama kami mendidik putra-putri tercinta menjadi insan yang beraqidah lurus, beribadah benar, berakhlak mulia, berilmu luas, mandiri, dan siap berkhidmat bagi umat dan bangsa.</p><p><strong>Wassalamu\'alaikum Warahmatullahi Wabarakatuh</strong><br><em>Mudir PPRU Sakatiga, KH. Tol\'at Wafa Ahmad, Lc.</em></p>', NULL, NULL, NULL, '2026-09-14 07:05:23', '2026-09-14 07:05:23'),
(2, 'Tentang Pondok Pesantren Raudhatul Ulum Sakatiga', 'tentang-kami', NULL, '<p>Pondok Pesantren Raudhatul Ulum (PPRU) Sakatiga adalah lembaga pendidikan Islam yang dikelola oleh Yayasan Perguruan Islam Raudhatul Ulum Sakatiga (YAPIRUS), berlokasi di Desa Sakatiga, Kecamatan Indralaya, Kabupaten Ogan Ilir, Sumatera Selatan (sekitar 40 km dari Kota Palembang).</p><p>Berdiri di atas lahan lebih dari 60 hektar yang mencakup Kampus A, Kampus B, dan Kampus C, lingkungan PPRU tertata asri, berwawasan lingkungan, dan sangat kondusif bagi tumbuh kembang santri. Pesantren menyelenggarakan pendidikan terpadu mulai dari jenjang anak usia dini (TAKIRU), dasar (MIRU), menengah (MATSARU, MARU, SMPIT, SMAIT), program khusus Tahfidzul Qur\'an Lil Aulad (MATQULARU), hingga perguruan tinggi (STITRU).</p>', NULL, NULL, NULL, '2026-09-14 07:05:23', '2026-09-14 07:05:23'),
(3, 'Visi, Misi, dan 10 Jati Diri Santri', 'visi-dan-misi', NULL, '<h3>VISI</h3><p><em>\"Menjadi basis kaderisasi generasi terbaik (Khoiru Ummah) yang bermanfaat luas dan berdaya saing global.\"</em></p><h3>MISI</h3><ol><li><strong>Ta\'lim:</strong> Menyelenggarakan kegiatan pengajaran secara utuh dan terpadu untuk menyiapkan sumber daya insani yang berwawasan luas dan menguasai ilmu syar\'i serta sains teknologi.</li><li><strong>Tarbiyah:</strong> Menginternalisasi nilai-nilai Islam kepada santri untuk membentuk kepribadian berkarakter mulia, kokoh secara moral, spiritual, dan emosional.</li><li><strong>Dakwah:</strong> Melatih dan membekali santri keterampilan dakwah Islamiyah, kepekaan sosial, serta kesiapan menegakkan amar ma\'ruf nahi munkar di tengah masyarakat.</li></ol><h3>10 JATI DIRI SANTRI (SDI RAUDHATUL ULUM)</h3><ol><li>Beraqidah lurus (Salimul Aqidah)</li><li>Beribadah benar (Shahihul Ibadah)</li><li>Berakhlak mulia (Matinul Khuluq)</li><li>Berdikari / Mandiri (Qadirun \'alal Kasbi)</li><li>Berpengetahuan luas (Mutsaqqoful Fikri)</li><li>Berbadan sehat dan kuat (Qowiyyul Jismi)</li><li>Mampu mengendalikan hawa nafsu (Mujahidun li Nafsihi)</li><li>Berdisiplin tinggi (Munazzhomun fi Syu\'unihi)</li><li>Mampu mengelola waktu (Haritsun \'ala Waqtihi)</li><li>Bermanfaat bagi masyarakat (Nafi\'un li Ghairihi)</li></ol>', NULL, NULL, NULL, '2026-09-14 07:05:23', '2026-09-14 07:05:23'),
(4, 'Sejarah Perkembangan Pondok Pesantren Raudhatul Ulum', 'sejarah', NULL, '<p>Sejarah Pondok Pesantren Raudhatul Ulum Sakatiga terbagi ke dalam tiga fase bersejarah:</p><h4>1. Era Cikal Bakal (1930 - 1950 M)</h4><p>PPRU berakar dari dua madrasah bersejarah di Sakatiga sebelum kemerdekaan RI: Madrasah Al-Falah yang didirikan pada tahun 1930 oleh KH. Bahri bin Bunga (dilanjutkan KH. Abdul Ghanie Bahri) dan Madrasah Al-Shibyan yang dirintis pada tahun 1936 oleh KH. Abd. Rahim Mandung dan KH. Abdullah Kenalim. Desa Sakatiga sejak masa itu telah masyhur dijuluki sebagai \"Mekkah Kecil\" di Sumatera Selatan karena banyaknya ulama asal Sakatiga yang menuntut ilmu di tanah suci Mekkah.</p><h4>2. Era Lanjutan Perjuangan (1950 - 1986 M)</h4><p>Pada 1 Agustus 1950, para tokoh dan ulama Sakatiga bersepakat menghidupkan kembali madrasah dengan mendirikan Sekolah Rakyat Islam (SRI) dan Sekolah Menengah Agama Islam (SMAI), yang kemudian disederhanakan menjadi Perguruan Islam Raudhatul Ulum Sakatiga (PIRUS) di bawah naungan YAPIRUS (Akte Notaris Aminus No. 21.A Tahun 1966).</p><h4>3. Era Modern & Boarding School (1986 - Sekarang)</h4><p>Mulai 8 Agustus 1986 di bawah kepemimpinan Mudir KH. Tol\'at Wafa Ahmad, Lc., diterapkan sistem terpadu antara kurikulum Pondok Modern Darussalam Gontor, Departemen Agama, dan Departemen Pendidikan Nasional dengan asrama penuh (boarding school). Jenjang madrasah aliyah dan tsanawiyah PPRU juga mendapatkan piagam muadalah pengakuan kesetaraan dari Universitas Al-Azhar Kairo Mesir dan Universitas Islam Madinah.</p>', NULL, NULL, NULL, '2026-09-14 07:05:23', '2026-09-14 07:05:23');
INSERT INTO `pengumumen` (`id`, `title`, `slug`, `content`, `file_attachment`, `status`, `featured_image`, `created_at`, `updated_at`) VALUES
(72, 'Pengumuman Hasil Kelulusan Seleksi Santri Baru (PSB) Gelombang 1 T.A. 2026/2027', 'pengumuman-kelulusan-psb-gelombang-1-ppru', '<p>Diumumkan kepada seluruh calon santri dan wali santri bahwa hasil seleksi berkas, tes lisan Al-Qur\'an, dan ujian akademik PSB Gelombang 1 telah resmi diterbitkan. Silakan periksa status kelulusan di portal PSB online dan lakukan daftar ulang sebelum batas waktu yang ditentukan.</p>', NULL, 'publish', '/uploads/ppru-gedung-utama.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(73, 'Maklumat Libur Hari Raya & Jadwal Kembali Santri ke Pondok Pesantren', 'maklumat-libur-hari-raya-dan-jadwal-kembali-santri-ppru', '<p>Berdasarkan keputusan Rapat Pimpinan Ma\'had, jadwal perpulangan santri dan batas waktu kedatangan kembali ke kampus Raudhatul Ulum telah ditetapkan. Seluruh santri wajib mematuhi ketentuan disiplin kepulangan dan membawa kartu perpulangan bermaterai.</p>', NULL, 'publish', '/uploads/ppru-masjid-agung.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(74, 'Panduan Tata Cara Pembayaran Syahriah via Virtual Account BSI & Bank Sumsel Babel Syariah', 'panduan-pembayaran-syahriah-virtual-account-ppru', '<p>Untuk memudahkan transaksi wali santri, pembayaran SPP/Syahriah, uang asrama, dan katering santri kini dilayani otomatis 24 jam melalui nomor Virtual Account masing-masing santri via Mobile Banking, ATM, dan transfer antarbank.</p>', NULL, 'publish', '/uploads/ppru-perpustakaan-islam.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(75, 'Petunjuk Teknis Ujian Nihai (Akhir) Santri KMI & Asesmen Madrasah 2026', 'petunjuk-teknis-ujian-nihai-santri-kmi-ppru', '<p>Panduan lengkap tata tertib, jadwal mata pelajaran tahriri dan syafahi, serta kriteria kelulusan muadalah bagi santri kelas akhir Kulliyatul Mu\'allimin Al-Islamiyyah dan Madrasah Aliyah Raudhatul Ulum.</p>', NULL, 'publish', '/uploads/ppru-wisuda-akbar.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(76, 'Pengumuman Penetapan Musyrif Asrama & Halaqah Tahfidz Santri Semester Genap', 'penetapan-musyrif-asrama-halaqah-tahfidz-ppru', '<p>Bagian Pengasuhan Santri PPRU mengumumkan daftar wali asrama, pembagian kamar santri, serta nama-nama muhaffizh pembimbing halaqah Al-Qur\'an demi menjaga kedisiplinan dan capaian hafalan santri.</p>', NULL, 'publish', '/uploads/ppru-halaqah-quran.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(77, 'Edaran Tata Tertib Kunjungan Wali Santri & Protokol Kedisiplinan Ma\'had', 'edaran-tata-tertib-kunjungan-wali-santri-ppru', '<p>Waktu sambang/kunjungan orang tua wali santri dibuka secara tertib setiap hari Ahad pada jam yang ditentukan. Dilarang membawa makanan instan berlebih, gawai/handphone terlarang, serta wajib berbusana muslim/muslimah rapi dan sopan.</p>', NULL, 'publish', '/uploads/ppru-panahan-santri.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(78, 'Informasi Beasiswa Prestasi Tahfidz 30 Juz & Kader Ulama Kerjasama BAZNAS', 'informasi-beasiswa-prestasi-tahfidz-ppru', '<p>Peluang beasiswa pendidikan penuh bagi santri berprestasi hafizh Qur\'an 30 juz dan anak yatim/dhuafa berprestasi akademik untuk jenjang MTs, MA, SMA IT, dan Institut Agama Islam Nur Raudhatul Ulum.</p>', NULL, 'publish', '/uploads/ppru-debat.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(79, 'Jadwal Layanan Pos Kesehatan Pesantren (Poskestren) & Vaksinasi Santri', 'jadwal-layanan-kesehatan-poskestren-ppru', '<p>Pusat Pelayanan Kesehatan Santri PPRU bekerjasama dengan Dinas Kesehatan dan Rumah Sakit Mitra membuka layanan pemeriksaan kesehatan berkala, dokter spesialis, serta klinik gigi santri setiap pekan.</p>', NULL, 'publish', '/uploads/ppru-robotika-sains.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(80, 'Pemberitahuan Pendaftaran Ekstrakurikuler Wajib & Pilihan Santri Baru', 'pendaftaran-ekstrakurikuler-santri-ppru', '<p>Daftar pilihan kegiatan minat bakat santri: Kepanduan Pramuka (wajib), Tapak Suci / Pencak Silat, Panahan Tradisional, Karya Ilmiah Remaja, Robotika, Kaligrafi, Muhadharah 3 Bahasa, Jurnalistik, dan Hadroh Marawis.</p>', NULL, 'publish', '/uploads/ppru-pencak-silat.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(81, 'Jadwal Pendaftaran Ulang & Pembagian Perlengkapan Santri Baru T.A. 2026/2027', 'jadwal-daftar-ulang-perlengkapan-santri-baru-ppru', '<p>Wali santri yang telah dinyatakan lulus seleksi diwajibkan melakukan konfirmasi ukuran seragam pondok, lemari asrama, kasur santri, dan kitab-kitab kurikulum di bagian inventaris Koperasi Pesantren PPRU.</p>', NULL, 'publish', '/uploads/ppru-sarasehan.webp', '2026-09-14 09:40:24', '2026-09-14 09:40:24'),
(82, 'Pengumuman Kelulusan Seleksi Penerimaan Santri Baru (PSB) Gelombang I T.A. 2026/2027', 'pengumuman-kelulusan-seleksi-penerimaan-santri-baru-psb-gelombang-i-ta-20262027', 'Diberitahukan kepada seluruh calon wali santri bahwa hasil seleksi tes akademik, membaca Al-Qur\'an, dan wawancara PSB Gelombang I telah resmi diumumkan. Silakan login ke portal PPDB Online untuk mengunduh surat ketetapan kelulusan.', NULL, 'publish', NULL, '2026-09-20 16:12:41', '2026-09-20 16:12:41'),
(83, 'Jadwal Kedatangan Santri & Tata Tertib Masuk Asrama Tahun Ajaran 2026/2027', 'jadwal-kedatangan-santri-tata-tertib-masuk-asrama-tahun-ajaran-20262027', 'Seluruh santri lama dan santri baru diwajibkan melakukan check-in asrama sesuai pembagian jadwal per unit guna menjaga ketertiban arus lalu lintas dan kelancaran serah terima santri bersama musyrif/musyrifah.', NULL, 'publish', NULL, '2026-09-20 16:12:41', '2026-09-20 16:12:41'),
(84, 'Surat Edaran Libur Hari Raya Idul Fitri 1447 H & Kalender Akademik Pesantren', 'surat-edaran-libur-hari-raya-idul-fitri-1447-h-kalender-akademik-pesantren', 'Berdasarkan keputusan pimpinan pesantren, perpulangan santri dalam rangka libur Idul Fitri dimulai secara bertahap. Wali santri dihimbau menjemput tepat waktu dan memperhatikan batas akhir kembali ke asrama.', NULL, 'publish', NULL, '2026-09-20 16:12:41', '2026-09-20 16:12:41'),
(85, 'Panduan Registrasi Ulang & Pembayaran Syahriyah Melalui Virtual Account Bank', 'panduan-registrasi-ulang-pembayaran-syahriyah-melalui-virtual-account-bank', 'Untuk mempermudah layanan administrasi keuangan santri secara transparan dan real-time, seluruh transaksi pembayaran kini menggunakan nomor Virtual Account resmi Bank Syariah Indonesia (BSI) dan Bank Sumsel Babel Syariah.', NULL, 'publish', NULL, '2026-09-20 16:12:41', '2026-09-20 16:12:41');
INSERT INTO `posts` (`id`, `title`, `slug`, `content`, `excerpt`, `status`, `is_featured`, `type`, `featured_image`, `featured_image_caption`, `views_count`, `author_id`, `unit_pendidikan_id`, `author_name`, `published_at`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) VALUES
(256, 'Haflah dan Wisuda Qur\'an Angkatan IV : Menjadi Generasi Cinta Al-Qur\'an', 'haflah-dan-wisuda-quran-angkatan-iv-menjadi-generasi-cinta-al-quran', '<p>Haflah dan Wisuda Qur\'an Gaza Angkatan IV: Menjadi Generasi Cinta Al-Qur\'anrnrnAlhamdulillah, momen penuh keberkahan dan haru kembali hadir dalam acara Haflah dan Wisuda Qur\'an Gaza Angkatan IV yang berlangsung dengan khidmat dan penuh makna (6 Mei 2025) ❤️.rnrnAcara ini menjadi bentuk apresiasi atas perjuangan dan kesungguhan para santri dalam menghafal kalamullah. Di antaranya adalah ananda Gaza, yang telah menyelesaikan hafalan dengan baik. Semoga Allah senantiasa menjaga hafalannya dan menjadikannya pribadi yang senantiasa mengamalkan Al-Qur’an dalam kehidupan sehari-hari.rnrnAcara semakin bermakna dengan hadirnya Ust. Heri Sholeh, L.C, yang memberikan motivasi dan nasihat mendalam tentang pentingnya menjadikan Al-Qur’an sebagai pedoman hidup. Beliau mengingatkan bahwa Al-Qur’an bukan hanya untuk dihafal, tapi untuk dipahami, diamalkan, dan dijadikan cahaya penuntun dalam setiap langkah kehidupan.rnrnWisuda Qur’an ini bukanlah akhir dari perjalanan, melainkan awal dari komitmen panjang untuk terus bersama Al-Qur’an. Menjadi generasi cinta Al-Qur’an berarti terus memperbaiki diri, memperkuat hafalan, dan menjadikan Al-Qur’an sebagai dasar dalam bersikap dan bertindak.rnrnSemoga:rnrnSetiap huruf yang dihafal menjadi cahaya di dunia dan akhiratrnrnPara santri terus istiqomah dalam menjaga hafalanrnrnKita semua terinspirasi menjadi bagian dari generasi Qur’ani yang diridhai Allahrnrn&nbsp;rnrn---rnrn📌 #HafalanQuran #WisudaQuran #CintaAlQuranrnrn&nbsp;</p>', 'Haflah dan Wisuda Qur\'an Gaza Angkatan IV: Menjadi Generasi Cinta Al-Qur\'anrnrnAlhamdulillah, momen penuh keberkahan dan haru kembali hadir dalam acara Haflah d...', 'publish', 0, 'post', '/uploads/2026/09/ppru-gedung-utama-1789405236-Et15a.webp', NULL, 1610, 4, NULL, NULL, '2025-07-08 02:37:17', 'Haflah dan Wisuda Qur\'an Angkatan IV : Menjadi Generasi Cinta Al-Qur\'an - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Haflah dan Wisuda Qur\'an Gaza Angkatan IV: Menjadi Generasi Cinta Al-Qur\'anrnrnAlhamdulillah, momen penuh keberkahan dan haru kembali hadir dalam acar...', NULL, '2026-09-11 08:07:23', '2026-09-20 21:20:55'),
(257, 'OUTING CLASS - Swimming Time', 'outing-class-swimming-time', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">*Outing Class Swimming Time: Keseruan di Air*</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Pada tanggal 23 April 2025, siswa-siswa sekolah melaksanakan outing class swimming time yang sangat dinantikan. Kegiatan ini dibagi menjadi 2 sesi untuk memastikan keselamatan dan kenyamanan semua peserta.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">*Sesi 1: Siswa dan Guru Laki-Laki*</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Sesi pagi dimulai pukul 08.00 hingga 10.00 WIB, khusus untuk siswa dan guru laki-laki. Kegiatan ini sangat disambut baik oleh peserta, yang dapat menikmati waktu berenang dan bermain air bersama. Mereka dapat menunjukkan kemampuan renang mereka dan bermain permainan air yang menyenangkan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">*Sesi 2: Siswa dan Guru Perempuan*</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Sesi siang dimulai pukul 10.00 hingga 12.00 WIB. Kegiatan ini juga sangat dinantikan oleh peserta, yang dapat menikmati waktu berenang dan bermain air bersama. Mereka dapat menunjukkan kemampuan renang mereka dan bermain permainan air yang menyenangkan.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">*Keseruan dan Manfaat*</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Kegiatan outing class swimming time ini tidak hanya memberikan kesempatan untuk berolahraga, tetapi juga untuk bersenang-senang dan melepas stres. Peserta dapat menikmati waktu bersama teman-teman dan meningkatkan keterampilan sosial mereka.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">*Kesimpulan*</p><p style=\"text-align: justify;\">Outing class swimming time pada tanggal 23 April 2025 merupakan kegiatan yang sangat sukses dan menyenangkan. Pembagian sesi pagi dan siang memastikan keselamatan dan kenyamanan semua peserta. Kegiatan ini dapat meningkatkan kesehatan fisik dan mental siswa, serta meningkatkan keterampilan sosial mereka.</p>', '*Outing Class Swimming Time: Keseruan di Air*nPada tanggal 23 April 2025, siswa-siswa sekolah melaksanakan outing class swimming time yang sangat dinantikan. Ke...', 'publish', 0, 'post', '/uploads/2026/09/ppru-gedung-utama-1789405221-FrKaT.webp', NULL, 877, 4, NULL, NULL, '2025-04-30 05:17:42', 'OUTING CLASS - Swimming Time - Pondok Pesantren Raudhatul Ulum Sakatiga', '*Outing Class Swimming Time: Keseruan di Air*nPada tanggal 23 April 2025, siswa-siswa sekolah melaksanakan outing class swimming time yang sangat dina...', NULL, '2026-09-11 08:07:23', '2026-09-20 20:44:24'),
(359, 'Sambutan Mudir Pondok Pesantren Raudhatul Ulum', 'sambutan-kepala-sekolah', '<h2>Assalamu\'alaikum Warahmatullahi Wabarakatuh</h2><p>Segala puji dan syukur kita panjatkan ke hadirat Allah Subhanahu wa Ta\'ala, yang telah melimpahkan rahmat, taufiq, dan inayah-Nya kepada kita semua. Shalawat dan salam senantiasa tercurahkan kepada junjungan kita Nabi Besar Muhammad Shallallahu \'Alaihi Wasallam, keluarga, sahabat, dan pengikutnya yang setia hingga akhir zaman.</p><p>Pondok Pesantren Raudhatul Ulum Sakatiga sejak didirikannya pada tanggal 1 Agustus 1950, bertekad menjadi benteng pertahanan aqidah umat dan basis kaderisasi generasi terbaik (Khoiru Ummah). Memadukan kurikulum kepesantrenan terpadu (Pondok Modern Gontor), Kementerian Agama, serta kurikulum nasional, santri dibina selama 24 jam dalam lingkungan asrama yang asri, disiplin, dan islami.</p><p>Kami menyambut hangat para orang tua/wali santri dan masyarakat luas yang ingin bermitra bersama kami mendidik putra-putri tercinta menjadi insan yang beraqidah lurus, beribadah benar, berakhlak mulia, berilmu luas, mandiri, dan siap berkhidmat bagi umat dan bangsa.</p><p><strong>Wassalamu\'alaikum Warahmatullahi Wabarakatuh</strong><em>Mudir PPRU Sakatiga, KH. Tol\'at Wafa Ahmad, Lc.</em></p>', 'Sambutan resmi Kepala Sekolah Pondok Pesantren Raudhatul Ulum Sakatiga, KH. Tol\'at Wafa Ahmad, Lc..', 'publish', 0, 'page', '/uploads/kh-tolat-wafa-ahmad.webp', NULL, 0, 4, NULL, NULL, '2026-09-14 08:27:45', 'Sambutan Kepala Sekolah - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Pesan dan komitmen pembinaan karakter, iman, dan ilmu di Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-11 08:07:24', '2026-09-17 06:55:12'),
(360, 'Visi, Misi, dan 10 Jati Diri Santri', 'visi-dan-misi', '<h3>VISI</h3><p><em>\"Menjadi basis kaderisasi generasi terbaik (Khoiru Ummah) yang bermanfaat luas dan berdaya saing global.\"</em></p><h3>MISI</h3><ol><li><strong>Ta\'lim:</strong> Menyelenggarakan kegiatan pengajaran secara utuh dan terpadu untuk menyiapkan sumber daya insani yang berwawasan luas dan menguasai ilmu syar\'i serta sains teknologi.</li><li><strong>Tarbiyah:</strong> Menginternalisasi nilai-nilai Islam kepada santri untuk membentuk kepribadian berkarakter mulia, kokoh secara moral, spiritual, dan emosional.</li><li><strong>Dakwah:</strong> Melatih dan membekali santri keterampilan dakwah Islamiyah, kepekaan sosial, serta kesiapan menegakkan amar ma\'ruf nahi munkar di tengah masyarakat.</li></ol><h3>10 JATI DIRI SANTRI (SDI RAUDHATUL ULUM)</h3><ol><li>Beraqidah lurus (Salimul Aqidah)</li><li>Beribadah benar (Shahihul Ibadah)</li><li>Berakhlak mulia (Matinul Khuluq)</li><li>Berdikari / Mandiri (Qadirun \'alal Kasbi)</li><li>Berpengetahuan luas (Mutsaqqoful Fikri)</li><li>Berbadan sehat dan kuat (Qowiyyul Jismi)</li><li>Mampu mengendalikan hawa nafsu (Mujahidun li Nafsihi)</li><li>Berdisiplin tinggi (Munazzhomun fi Syu\'unihi)</li><li>Mampu mengelola waktu (Haritsun \'ala Waqtihi)</li><li>Bermanfaat bagi masyarakat (Nafi\'un li Ghairihi)</li></ol>', 'Visi & Misi resmi Pondok Pesantren Raudhatul Ulum Sakatiga menuju generasi emas tanggap, tangkas, dan tangguh.', 'publish', 0, 'page', '/uploads/logo-PPRU.webp', NULL, 0, 4, NULL, NULL, '2026-09-14 08:27:45', 'Visi dan Misi - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Visi dan Misi pendidikan Islam terpadu Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-11 08:07:24', '2026-09-14 08:27:45'),
(361, 'Tentang Pondok Pesantren Raudhatul Ulum Sakatiga', 'tentang-kami', '<p style=\"text-align: justify;\">Pondok Pesantren Raudhatul Ulum (PPRU) Sakatiga adalah lembaga pendidikan Islam yang dikelola oleh Yayasan Perguruan Islam Raudhatul Ulum Sakatiga (YAPIRUS), berlokasi di Desa Sakatiga, Kecamatan Indralaya, Kabupaten Ogan Ilir, Sumatera Selatan (sekitar 40 km dari Kota Palembang).</p><p style=\"text-align: justify;\">Berdiri di atas lahan lebih dari 60 hektar yang mencakup pondok A, pondok B, dan pondok C, lingkungan PPRU tertata asri, berwawasan lingkungan, dan sangat kondusif bagi tumbuh kembang santri. Pesantren menyelenggarakan pendidikan terpadu mulai dari jenjang anak usia dini (TAKIRU), dasar (MIRU), menengah (MATSARU, MARU, SMPIT, SMAIT), program khusus Tahfidzul Qur\'an Lil Aulad (MATQULARU), hingga perguruan tinggi (STITRU).</p>', 'Profil singkat Pondok Pesantren Raudhatul Ulum Sakatiga: Kurikulum terpadu JSIT dan Kurikulum Merdeka.', 'publish', 0, 'page', '/uploads/logo-PPRU.webp', NULL, 0, 4, NULL, NULL, '2026-09-14 08:27:45', 'Tentang Kami - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Profil Pondok Pesantren Raudhatul Ulum Sakatiga, sekolah Islam terpadu di Sakatiga Ogan Ilir.', NULL, '2026-09-11 08:07:24', '2026-09-17 08:15:03'),
(362, 'Sejarah Perkembangan Pondok Pesantren Raudhatul Ulum', 'sejarah', '<p>Sejarah Pondok Pesantren Raudhatul Ulum Sakatiga terbagi ke dalam tiga fase bersejarah:</p><h4>1. Era Cikal Bakal (1930 - 1950 M)</h4><p>PPRU berakar dari dua madrasah bersejarah di Sakatiga sebelum kemerdekaan RI: Madrasah Al-Falah yang didirikan pada tahun 1930 oleh KH. Bahri bin Bunga (dilanjutkan KH. Abdul Ghanie Bahri) dan Madrasah Al-Shibyan yang dirintis pada tahun 1936 oleh KH. Abd. Rahim Mandung dan KH. Abdullah Kenalim. Desa Sakatiga sejak masa itu telah masyhur dijuluki sebagai \"Mekkah Kecil\" di Sumatera Selatan karena banyaknya ulama asal Sakatiga yang menuntut ilmu di tanah suci Mekkah.</p><h4>2. Era Lanjutan Perjuangan (1950 - 1986 M)</h4><p>Pada 1 Agustus 1950, para tokoh dan ulama Sakatiga bersepakat menghidupkan kembali madrasah dengan mendirikan Sekolah Rakyat Islam (SRI) dan Sekolah Menengah Agama Islam (SMAI), yang kemudian disederhanakan menjadi Perguruan Islam Raudhatul Ulum Sakatiga (PIRUS) di bawah naungan YAPIRUS (Akte Notaris Aminus No. 21.A Tahun 1966).</p><h4>3. Era Modern & Boarding School (1986 - Sekarang)</h4><p>Mulai 8 Agustus 1986 di bawah kepemimpinan Mudir KH. Tol\'at Wafa Ahmad, Lc., diterapkan sistem terpadu antara kurikulum Pondok Modern Darussalam Gontor, Departemen Agama, dan Departemen Pendidikan Nasional dengan asrama penuh (boarding school). Jenjang madrasah aliyah dan tsanawiyah PPRU juga mendapatkan piagam muadalah pengakuan kesetaraan dari Universitas Al-Azhar Kairo Mesir dan Universitas Islam Madinah.</p>', 'Sejarah berdirinya Pondok Pesantren Raudhatul Ulum Sakatiga.', 'publish', 0, 'page', '/uploads/logo-PPRU.webp', NULL, 0, 4, NULL, NULL, '2026-09-14 08:27:46', 'Sejarah - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Sejarah perjalanan pendirian Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-11 08:07:24', '2026-09-14 08:27:46'),
(363, 'Struktur Organisasi', 'struktur-organisasi', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Struktur kepemimpinan dan manajemen Pondok Pesantren Raudhatul Ulum Sakatiga dipimpin oleh Kepala Sekolah KH. Tol\'at Wafa Ahmad, Lc., didampingi oleh Wakil Kepala Sekolah Bidang Kurikulum Anita Carlyna, S.IP., M.Pd, serta staf pendidik dan tenaga kependidikan profesional.</p>', 'Bagan susunan struktur pimpinan dan manajemen Pondok Pesantren Raudhatul Ulum Sakatiga.', 'publish', 0, 'page', '/uploads/logo-PPRU.webp', NULL, 0, 4, NULL, NULL, '2026-09-12 00:03:45', 'Struktur Organisasi - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Susunan pimpinan dan tata kelola Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-11 08:07:24', '2026-09-14 08:01:37'),
(364, 'Infaq & Wakaf Pembangunan Pondok Pesantren Raudhatul Ulum', 'donasi', '<h3>Investasi Akhirat Melalui Pendidikan Islam</h3><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Yayasan Pondok Pesantren Raudhatul Ulum Sakatiga membuka kesempatan seluas-luasnya bagi kaum muslimin dan para dermawan untuk menyalurkan infaq dan sedekah jariyah. Dana yang terhimpun disalurkan untuk pembangunan sarana laboratorium, mushola, ruang kelas baru, dan beasiswa pendidikan santri berprestasi.</p>', 'Salurkan infaq dan wakaf terbaik Anda untuk sarana pendidikan Islam dan beasiswa tahfidz di Kota Sakatiga Ogan Ilir.', 'publish', 0, 'page', '/uploads/logo-PPRU.webp', NULL, 0, NULL, NULL, NULL, NULL, 'Infaq & Wakaf Pembangunan Pondok Pesantren Raudhatul Ulum Sakatiga', 'Salurkan infaq dan wakaf terbaik Anda untuk sarana pendidikan Islam dan beasiswa tahfidz di Kota Sakatiga Ogan Ilir.', NULL, '2026-09-11 08:07:24', '2026-09-14 08:01:37'),
(365, 'E-Library & Modul Pembelajaran Pondok Pesantren Raudhatul Ulum Sakatiga', 'e-book', '<h3>Pusat E-Library & Buku Digital</h3><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Daftar koleksi buku pelajaran Kurikulum Merdeka, modul guru, dan bacaan islami yang dapat diakses dan diunduh oleh civitas akademika Pondok Pesantren Raudhatul Ulum Sakatiga.</p>', 'Kumpulan buku pelajaran, panduan kurikulum, dan modul e-library santri Pondok Pesantren Raudhatul Ulum Sakatiga.', 'publish', 0, 'page', '/uploads/logo-PPRU.webp', NULL, 0, NULL, NULL, NULL, NULL, 'E-Library & Modul Pembelajaran Pondok Pesantren Raudhatul Ulum Sakatiga', 'Kumpulan buku pelajaran, panduan kurikulum, dan modul e-library santri Pondok Pesantren Raudhatul Ulum.', NULL, '2026-09-11 08:07:24', '2026-09-14 08:01:37'),
(366, 'Mars & Hymne Jaringan Sekolah Islam Terpadu', 'hymne-mars', '<h3>Mars JSIT Indonesia</h3><p class=\"italic text-gray-600 ql-align-justify\" style=\"text-align: justify; text-justify: inter-word;\">Membina tunas bangsa, beriman dan bertaqwa, cerdas berakhlak mulia...</p>', 'Lagu mars dan hymne Sekolah Islam Terpadu kebanggaan Pondok Pesantren Raudhatul Ulum.', 'publish', 0, 'page', '/uploads/logo-PPRU.webp', NULL, 0, NULL, NULL, NULL, NULL, 'Mars & Hymne Jaringan Sekolah Islam Terpadu', 'Lagu mars dan hymne Sekolah Islam Terpadu kebanggaan Pondok Pesantren Raudhatul Ulum.', NULL, '2026-09-11 08:07:24', '2026-09-14 08:01:37'),
(367, 'Logo Resmi Pondok Pesantren Raudhatul Ulum Sakatiga', 'logo', '<h3>Filosofi Logo Pondok Pesantren Raudhatul Ulum</h3><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Logo Pondok Pesantren Raudhatul Ulum Sakatiga memadukan lambang perisai keimanan, kubah masjid, Al-Qur\'an terbuka, dan obor semangat dengan skema warna dominan hijau Islami dan merah yang melambangkan keberanian, ketangguhan, serta cita-cita luhur menuju perbaikan umat.</p>', 'Makna filosofis lambang dan logo resmi Pondok Pesantren Raudhatul Ulum Sakatiga.', 'publish', 0, 'page', '/uploads/logo-PPRU.webp', NULL, 0, NULL, NULL, NULL, NULL, 'Logo Resmi Pondok Pesantren Raudhatul Ulum Sakatiga', 'Makna filosofis lambang dan logo resmi SMA Islam Terpadu Raudhatul Ulum Sakatiga Ogan Ilir.', NULL, '2026-09-11 08:07:24', '2026-09-14 08:01:37'),
(368, 'Kontak & Sekretariat PPDB Pondok Pesantren Raudhatul Ulum Sakatiga', 'hubungi', '<h3>Sekretariat Sekolah & Panitia PPDB</h3><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Silakan kunjungi pondok kami atau hubungi panitia PPDB untuk informasi pendaftaran peserta didik baru, jadwal seleksi, dan beasiswa.</p><p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\"><strong>Alamat:</strong> Jalan Sadewa RT 01 RW 03 Kel. Sakatiga, Kec. Sakatiga Ogan Ilir Timur, Kota Sakatiga Ogan Ilir, Sumatera Selatan 31111.<br><strong>WhatsApp / Telp:</strong> 0821-8268-0647<br><strong>Email:</strong> sekretariat@ppru.ac.id</p>', 'Alamat dan kontak resmi sekretariat Pondok Pesantren Raudhatul Ulum Sakatiga.', 'publish', 0, 'page', '/uploads/logo-PPRU.webp', NULL, 0, NULL, NULL, NULL, NULL, 'Kontak & Sekretariat PPDB Pondok Pesantren Raudhatul Ulum Sakatiga', 'Alamat dan kontak resmi sekretariat SMA Islam Terpadu Raudhatul Ulum Sakatiga Ogan Ilir.', NULL, '2026-09-11 08:07:24', '2026-09-14 08:01:37'),
(369, 'Kontak & Lokasi', 'kontak', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Silakan hubungi kami atau kunjungi pondok Pondok Pesantren Raudhatul Ulum Sakatiga di Jalan Sadewa RT 01 RW 03 Kelurahan Sakatiga Kecamatan Sakatiga Ogan Ilir Timur Kota Sakatiga Ogan Ilir.</p>', 'Kontak resmi, telepon, WhatsApp, email, dan alamat Pondok Pesantren Raudhatul Ulum.', 'publish', 0, 'page', '', NULL, 0, 4, NULL, NULL, '2026-09-12 00:03:45', 'Kontak Kami - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Hubungi Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-12 00:03:18', '2026-09-14 08:01:37'),
(370, 'Layanan Terpadu', 'layanan-terpadu-2', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Layanan Terpadu Pondok Pesantren Raudhatul Ulum Sakatiga melayani berbagai permohonan administrasi secara transparan dan mudah, antara lain:</p><ul><li><strong>Permohonan Izin Kunjungan ke Sekolah:</strong> Pengajuan kunjungan edukatif, studi banding, atau instansi.</li><li><strong>Permohonan Kerja Sama:</strong> Kemitraan lembaga, magang, beasiswa, dan sponsorship.</li><li><strong>Permohonan Sewa Menyewa Barang / Fasilitas:</strong> Penyewaan aula, sarana olahraga, dan fasilitas sekolah.</li></ul>', 'Layanan administrasi terpadu Pondok Pesantren Raudhatul Ulum Sakatiga.', 'publish', 0, 'page', '', NULL, 0, 4, NULL, NULL, '2026-09-12 00:03:45', 'Layanan Terpadu - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Portal permohonan dan layanan terpadu Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-12 00:03:18', '2026-09-14 08:01:37'),
(371, 'Permohonan Izin Kunjungan ke Sekolah', 'izin-sekolah', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Formulir dan prosedur permohonan izin kunjungan edukasi, studi banding, atau observasi ke Pondok Pesantren Raudhatul Ulum Sakatiga.</p>', 'Permohonan Izin Kunjungan ke Sekolah.', 'publish', 0, 'page', '', NULL, 0, 4, NULL, NULL, '2026-09-12 00:03:45', 'Permohonan Izin Kunjungan - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Pengajuan izin kunjungan resmi ke Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-12 00:03:18', '2026-09-14 08:01:37'),
(372, 'Permohonan Kerja Sama', 'permohonan-kerja-sama', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Layanan resmi permohonan kemitraan, kerjasama kelembagaan, dan kegiatan kolaboratif bersama Pondok Pesantren Raudhatul Ulum Sakatiga.</p>', 'Permohonan Kerja Sama Kelembagaan.', 'publish', 0, 'page', '', NULL, 0, 4, NULL, NULL, '2026-09-12 00:03:45', 'Permohonan Kerja Sama - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Kerjasama strategis dan kelembagaan bersama Pondok Pesantren Raudhatul Ulum.', NULL, '2026-09-12 00:03:18', '2026-09-14 08:01:37'),
(373, 'Permohonan Sewa Menyewa Barang Sekolah', 'sewa-barang', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Layanan dan ketentuan penyewaan fasilitas sekolah (Hall PPRU, laboratorium, perlengkapan event) bagi masyarakat dan instansi.</p>', 'Permohonan Sewa Menyewa Barang / Fasilitas Sekolah.', 'publish', 0, 'page', '', NULL, 0, 4, NULL, NULL, '2026-09-12 00:03:45', 'Permohonan Sewa Barang - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Ketentuan dan permohonan sewa sarana prasarana sekolah.', NULL, '2026-09-12 00:03:18', '2026-09-14 08:01:37'),
(374, 'Data Alumni', 'data-alumni', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Daftar alumni kebanggaan Pondok Pesantren Raudhatul Ulum Sakatiga yang telah melanjutkan pendidikan ke berbagai perguruan tinggi negeri, kedinasan, pondok Islam terkemuka, dan berkarier di berbagai sektor.</p>', 'Data alumni dan rekam jejak lulusan Pondok Pesantren Raudhatul Ulum.', 'publish', 0, 'page', '', NULL, 0, 4, NULL, NULL, '2026-09-12 00:03:45', 'Data Alumni - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Database alumni Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-12 00:03:18', '2026-09-14 08:01:37'),
(375, 'Informasi PPDB Online', 'ppdb-santri-baru-ppru-sakatiga-ogan-ilir', '<p style=\"text-align: justify; text-justify: inter-word;\" class=\"ql-align-justify\">Penerimaan Peserta Didik Baru (PPDB) Pondok Pesantren Raudhatul Ulum Sakatiga dibuka setiap tahun ajaran baru dengan jalur beasiswa tahfidz dan reguler. Pendaftaran dapat dilakukan langsung melalui portal online <a href=\"https://ppdb.smaitPPRUpbm.sch.id/\" target=\"_blank\" class=\"text-green-600 font-bold underline\">https://ppdb.smaitPPRUpbm.sch.id/</a>.</p>', 'Informasi pendaftaran siswa baru Pondok Pesantren Raudhatul Ulum Sakatiga.', 'publish', 0, 'page', '', NULL, 0, 4, NULL, NULL, '2026-09-12 00:03:45', 'PPDB Pondok Pesantren Raudhatul Ulum Sakatiga', 'Informasi PPDB Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-12 00:03:18', '2026-09-14 08:01:37'),
(376, 'Juara 4 Sambung Ayat Qur\'an', 'juara-4-sambung-ayat', '<p>Selamat dan sukses atas raihan Juara 4 Sambung Ayat Qur\'an oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.</p>', 'Selamat dan sukses atas raihan Juara 4 Sambung Ayat Qur\'an oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.', 'publish', 0, 'prestasi', '/uploads/2022/03/35.webp', NULL, 0, 4, NULL, NULL, '2022-03-31 02:12:24', 'Prestasi: Juara 4 Sambung Ayat Qur\'an - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Selamat dan sukses atas raihan Juara 4 Sambung Ayat Qur\'an oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-12 00:03:22', '2026-09-14 08:01:37'),
(377, 'Juara 1 Lomba Kaligrafi', 'juara-1-lomba-kaligrafi', '<p>Selamat dan sukses atas raihan Juara 1 Lomba Kaligrafi oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.</p>', 'Selamat dan sukses atas raihan Juara 1 Lomba Kaligrafi oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.', 'publish', 0, 'prestasi', '/uploads/2023/01/33.webp', NULL, 0, 4, NULL, NULL, '2023-01-20 08:45:00', 'Prestasi: Juara 1 Lomba Kaligrafi - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Selamat dan sukses atas raihan Juara 1 Lomba Kaligrafi oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-12 00:03:22', '2026-09-14 08:01:37'),
