(1, 'PPDB-2026-0001', 'Iola Bonner', 'Ipsum mollit amet', '1990-08-17', 'Laki-laki', 'Anim non ex tempora', 'Orang Tua', 15, 13, 'Accusamus labore vol', 'Mollit illum et est', 'Nulla consequuntur i', 'Molestiae sit dolore', 'Perspiciatis aut el', 'Facilis dolorum non', '+1 (704) 652-1604', 'Edward Conway', 'Eaque aut reprehende', '2012-09-10', 'Corporis culpa maio', 'SMA / SMK / MA', 'Guru / Dosen', 'Rp 1.000.000 - Rp 3.000.000', '+1 (859) 921-1232', 'Garth Walls', 'Veniam dolorum nequ', '2003-09-11', 'Sit non ut lorem qui', 'Sarjana (S1)', 'Wiraswasta / Pengusaha', '< Rp 1.000.000', '+1 (571) 154-1947', '/uploads/ppdb/akta/screencapture-school-test-program-unggulan-2026-09-12-16-01-10-1789204335-cg7jC.webp', '/uploads/ppdb/bukti/screencapture-school-test-program-unggulan-2026-09-12-16-01-10-1789204336-5fQzh.webp', 'pending', '2026/2027', NULL, '2026-09-12 02:12:16', '2026-09-12 02:12:16', NULL, NULL, NULL, NULL);
INSERT INTO `program_unggulans` (`id`, `name`, `slug`, `description`, `head_name`, `address`, `order`, `created_at`, `updated_at`, `thumbnail`) VALUES
(1, 'Program Tahfidz Mutqin 30 Juz', 'program-tahfidz-mutqin-30-juz', 'Bimbingan intensif membaca Al-Qur\'an dengan tartil, tahsin bersanad, dan hafalan mutqin serta program Munaqosah Tahfidz.', NULL, 'Kurikulum Khusus Keislaman PPRU', 1, '2026-09-14 08:27:46', '2026-09-14 12:09:43', '/uploads/program-tahfidz.jpg'),
(2, 'Bina Pribadi Islam (BPI) & Karakter Santri', 'bina-pribadi-islam-bpi', 'Halaqah pekanan pembinaan adab, pembiasaan ibadah yaumiyah, dzikir ma\'tsurat, serta penanaman 10 Jati Diri Santri Raudhatul Ulum.', NULL, 'Pembinaan Karakter Santri', 2, '2026-09-14 08:27:46', '2026-09-14 12:09:43', '/uploads/program-karakter.jpg'),
(3, 'Kurikulum Terpadu Muadalah Al-Azhar & Nasional', 'kurikulum-terpadu-muadalah-al-azhar', 'Memadukan standar capaian Kurikulum Nasional dengan kurikulum Muadalah Universitas Al-Azhar Kairo Mesir.', NULL, 'Integrasi Dirasah Islamiyah & Sains', 3, '2026-09-14 08:27:46', '2026-09-14 12:09:43', '/uploads/program-muadalah.jpg'),
(4, 'Program Bahasa Arab & Inggris Aktif (Bilingual)', 'program-bahasa-arab-inggris-bilingual', 'Pembiasaan muhadatsah harian, pidato 3 bahasa (Muhadharah), dan penguasaan kitab-kitab turots berbahasa Arab.', NULL, 'Pengembangan Bahasa Internasional', 4, '2026-09-14 08:27:46', '2026-09-14 12:09:43', '/uploads/program-bahasa.jpg'),
(5, 'Safar Ilmiah & Rihlah Edukatif', 'safar-ilmiah-rihlah-edukatif', 'Pembelajaran luar kelas berbasis observasi alam, studi pondok dalam dan luar negeri, dan riset ilmiah santri.', NULL, 'Outdoor Learning & Wawasan Global', 5, '2026-09-14 08:27:46', '2026-09-14 12:09:43', '/uploads/program-sains.jpg'),
(6, 'Khidmat Dakwah & Kemasyarakatan', 'khidmat-dakwah-kemasyarakatan', 'Kiprah nyata santri dalam Praktik Pengabdian Masyarakat (P2S/PPM) dan dakwah ke berbagai pelosok nusantara.', NULL, 'Kepedulian Sosial & Pengabdian Ummat', 6, '2026-09-14 08:27:46', '2026-09-14 12:09:43', '/uploads/program-dakwah.jpg');
