(100, 'ppdb_step_5_desc', 'Kedatangan santri ke asrama, serah terima dengan Mudir dan pengasuh, serta mengikuti Pekan Perkenalan Santri Baru (P2SB).', 'ppdb', '2026-09-14 13:49:06', '2026-09-14 13:49:06'),
(101, 'ppdb_step_5_sub', 'Khutbatul Arsy & pembagian kamar santri', 'ppdb', '2026-09-14 13:49:06', '2026-09-14 13:49:06'),
(102, 'ppdb_alur', 'Siapkan berkas foto/scan bukti transfer biaya pendaftaran melalui Bank Syariah Indonesia (BSI) nomor rekening 7011304251 a.n. Pondok Pesantren Raudhatul Ulum.\r\nSiapkan berkas foto/scan akta kelahiran dan kartu keluarga.\r\nMengisi formulir PPDB secara online pada website resmi.\r\nKonfirmasi pengisian formulir kepada panitia melalui WhatsApp (0812-7890-1950).\r\nPendaftaran selesai dan berkas diverifikasi tim panitia untuk tahapan tes wawancara dan tahfidz.', 'ppdb', '2026-09-14 13:49:06', '2026-09-14 13:49:06'),
(103, 'ppdb_jalur_title', 'JALUR PENERIMAAN SANTRI BARU', 'ppdb', '2026-09-14 13:49:06', '2026-09-14 13:49:06'),
(104, 'ppdb_jalur_desc', 'Tersedia berbagai pilihan jalur penerimaan sesuai bakat, hafalan Al-Qur\'an, dan prestasi santri', 'ppdb', '2026-09-14 13:49:06', '2026-09-14 13:49:06'),
(105, 'ppdb_jalur_reguler_title', 'Jalur Reguler (Mandiri)', 'ppdb', '2026-09-14 13:49:06', '2026-09-14 13:49:06'),
(106, 'ppdb_mandiri', 'Jalur umum melalui tahapan tes potensi akademik, tes membaca Al-Qur\'an (tahsin & tajwid), dan wawancara kesiapan santri & orang tua.', 'ppdb', '2026-09-14 13:49:06', '2026-09-14 13:49:06'),
(107, 'ppdb_jalur_tahfidz_title', 'Jalur Hafizh Al-Qur\'an', 'ppdb', '2026-09-14 13:49:06', '2026-09-14 13:49:06'),
(108, 'ppdb_jalur_prestasi_title', 'Jalur Prestasi Sains', 'ppdb', '2026-09-14 13:49:06', '2026-09-14 13:49:06'),
(109, 'ppdb_prestasi', 'Bebas tes tulis akademik bagi pemenang juara 1, 2, atau 3 lomba sains (KSM/OSN), MTQ/MHQ, pidato, dan olahraga tingkat kota, provinsi, atau nasional.', 'ppdb', '2026-09-14 13:49:06', '2026-09-14 13:49:06'),
