(160, 'hymne_mars_hero_badge', 'Mars Ponpes RU', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(161, 'hymne_mars_hero_title', 'Mars Pondok Pesantren Raudhatul Ulum', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(162, 'hymne_mars_hero_desc', 'Lagu kebanggaan civitas akademika Pondok Pesantren Raudhatul Ulum Sakatiga sebagai bagian dari Jaringan Sekolah Islam Terpadu (JSIT) Indonesia dalam membina generasi Rabbani yang unggul dan berdaya saing global.', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(163, 'hymne_mars_badge', 'Mars Resmi PPRU', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(164, 'hymne_mars_title', 'MARS PPRU', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(165, 'hymne_mars_subtitle', 'Pedoman semangat santri & pendidik Pondok Pesantren Raudhatul Ulum', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(166, 'hymne_mars_youtube_url', 'https://www.youtube.com/watch?v=ijDo1wLvZ6w', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(167, 'hymne_mars_youtube_btn_text', 'Tonton di YouTube', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(168, 'hymne_mars_lyrics_title', 'LIRIK MARS RESMI PPRU', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 14:15:35'),
(169, 'hymne_mars_lyrics_stanza_1', 'Dengan berbekal semangat kami melangkah\r\nMenjalin ukhuwah dengan tekad membaja\r\nMenuju mutu pendidikan Indonesia\r\nMelahirkan generasi cerdas mulia (2x)', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(170, 'hymne_mars_lyrics_reff_1', 'Kami Jaringan Sekolah Islam Terpadu\r\nSambut masa depan wajah Indonesia baru\r\nBersama tinggikan martabat dan citra guru\r\nIndonesia pasti maju! (pasti maju)', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(171, 'hymne_mars_lyrics_stanza_2', 'Di sinilah tempat kami berkarya\r\nMenggapai harapan meraih cita-cita\r\nSebagai penggerak dan pemberdaya bangsa\r\nWujudkan masyarakat cerdas dan sejahtera (2x)', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(172, 'hymne_mars_lyrics_reff_2', 'Kami Jaringan Sekolah Islam Terpadu\r\nBangkit serentak menyongsong peradaban baru\r\nBulatkan tekad dan cita membangun bangsa\r\nIndonesia maju dan berjaya! (dan berjaya)', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(173, 'hymne_mars_philo_title', 'Makna & Semangat Mars PPRU', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(174, 'hymne_mars_philo_desc', 'Mars JSIT Indonesia mencerminkan tekad luhur seluruh lembaga pendidikan Islam terpadu di Indonesia untuk mencetak generasi berkarakter salimul aqidah, shahihul ibadah, dan berprestasi sains teknologi tingkat dunia.', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(175, 'hymne_mars_creator_name', 'Tim Pengembang PPRU', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(176, 'hymne_mars_audio_url', '/uploads/downloads/mars-jsit-indonesia.mp3', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
(177, 'hymne_mars_audio_btn_text', 'Unduh Audio Mars MP3', 'hymne_mars', '2026-09-20 13:25:10', '2026-09-20 13:25:10'),
