INSERT INTO `settings` (`id`, `key`, `value`, `group`, `created_at`, `updated_at`) VALUES
(218, 'home_sambutan_text_1', 'Selamat datang di gerbang informasi resmi Pondok Pesantren Raudhatul Ulum Sakatiga. Sejak dirintis di bumi Sakatiga yang berjuluk Mekkah Kecil, pesantren ini senantiasa berkomitmen menjaga kemurnian ajaran Islam.', 'general', '2026-09-20 15:45:29', '2026-09-20 15:45:29'),
(219, 'home_sambutan_text_2', 'Dengan integrasi kurikulum terpadu muadalah Al-Azhar Kairo dan pendidikan nasional, kami mengantarkan para santri menjadi ulama amilin dan cendekiawan muslim yang tangguh.', 'general', '2026-09-20 15:45:29', '2026-09-20 15:45:29'),
