(225, 'home_psb_title', 'Mari Bergabung Membentuk Generasi Qur\'ani Unggul Berdaya Saing Global', 'general', '2026-09-20 15:45:29', '2026-09-20 15:45:29'),
(226, 'home_psb_desc', 'Pendaftaran Santri Baru Tahun Ajaran 2026/2027 telah dibuka untuk seluruh jenjang: PAUD/TK, Madrasah Ibtidaiyah (MI), MTs, Madrasah Aliyah (MA), dan Sekolah Tinggi.', 'general', '2026-09-20 15:45:29', '2026-09-20 15:45:29'),
