INSERT INTO `testimonials` (`id`, `unit_pendidikan_id`, `name`, `profession`, `content`, `photo`, `status`, `created_at`, `updated_at`) VALUES
(1, NULL, 'Eva Astuti', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Anakku bernama Abdurrosyad Fadlillah saat ini duduk di kelas XI. Alhamdulillah sekarang sudah mulai berani tampil dan mandiri, sopan santun semakin baik. Semoga dengan bimbingan dari asatidz dan ustadzah di pondok, ananda semakin percaya diri, berakhlakul karimah, dan disiplin dalam ibadah maupun belajar. Aamiin ya Rabbal \'alamin.', NULL, 'publish', '2026-09-14 08:27:46', '2026-09-14 08:27:46'),
(2, NULL, 'Ayu Putri', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Toby Aldinata Timothy anakku santri baru tahun ini di Pondok Pesantren Raudhatul Ulum. Pembinaan karakternya sangat terasa sejak awal masuk. Semoga yang baik menjadi semakin baik lagi dan istiqomah.', NULL, 'publish', '2026-09-14 08:27:46', '2026-09-14 08:27:46'),
(3, NULL, 'Evi Riani', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Putri sulungku Seren Rahmadani saat ini duduk di kelas akhir. Alhamdulillah ada perubahan yang terus positif dan signifikan, hafalannya bertambah, mandiri, dan beradab sesuai nilai-nilai santri Raudhatul Ulum.', NULL, 'publish', '2026-09-14 08:27:46', '2026-09-14 08:27:46'),
(4, NULL, 'Penny Cahyani', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Najwa Rizkiya Ramadhani nama putriku yang saat ini duduk di kelas akhir. Kami sangat bersyukur menyekolahkannya di Pondok Pesantren Raudhatul Ulum Sakatiga. Semoga setelah lulus ananda bisa menjadi generasi berakhlak mulia yang bermanfaat bagi umat.', NULL, 'publish', '2026-09-14 08:27:46', '2026-09-14 08:27:46'),
(5, NULL, 'Yulianti Widiastuti', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Anakku bernama Annisa Dhiya Abelia saat ini sudah di kelas XII. Anak semakin percaya diri, hafalan Al-Qur\'annya terus bertambah mutqin, dan selalu berhati-hati serta berpegang teguh pada nilai-nilai agama dalam kesehariannya.', NULL, 'publish', '2026-09-14 08:27:46', '2026-09-14 08:27:46'),
(6, NULL, 'Dora Indah', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Anakku bernama Ragil Rizgy Putra duduk di kelas XI. Saya merasa membuat pilihan yang sangat tepat menitipkan anak di Pondok Pesantren Raudhatul Ulum Sakatiga. Kekeluargaan para asatidz dan pengasuh asrama membuat kami tenang, bersama membimbing anak-anak menuju sukses dunia dan akhirat. Aamiin.', NULL, 'publish', '2026-09-14 08:27:46', '2026-09-14 08:27:46'),
(7, NULL, 'Suharyanti', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Abi Anggara Santriyano adalah anak laki-lakiku yang saat ini duduk di kelas XII. PPRU terus mengutamakan kualitas pendidikan agama, tahfidz, dan akhlakul karimah. Para ustadz memberikan perhatian terbaik dan mendidik sepenuh hati.', NULL, 'publish', '2026-09-14 08:27:46', '2026-09-14 08:27:46'),
(8, NULL, 'Sugiarti', 'Alumni Pondok Pesantren Raudhatul Ulum', 'Setelah menempuh pendidikan di Pondok Pesantren Raudhatul Ulum, saya merasakan perubahan besar dalam hal kedisiplinan ibadah dan pergaulan. Ilmu agama dan wawasan yang didapat sangat mendalam, didukung lingkungan ukhuwah santri yang saling menyemangati dalam kebaikan.', NULL, 'publish', '2026-09-14 08:27:46', '2026-09-14 08:27:46'),
(9, NULL, 'Shella Destiani', 'Alumni Pondok Pesantren Raudhatul Ulum', 'Pondok Pesantren Raudhatul Ulum memiliki lingkungan yang sangat suportif, tanpa senioritas yang merugikan. Asatidz dan dewan guru sangat peduli, membimbing kami layaknya orang tua kedua. Bekal adab, Al-Qur\'an, dan kemandirian dari pondok menjadi modal berharga bagi saya saat melanjutkan pendidikan dan berkarier.', NULL, 'publish', '2026-09-14 08:27:46', '2026-09-14 08:27:46'),
(10, NULL, 'Toni Siswanto dan Widyaningtyastuti', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Assalamu\'alaikum warahmatullahi wabarakatuh. Kami orang tua dari ananda Yunita Andini Amalia bersyukur ananda menuntut ilmu di Pondok Pesantren Raudhatul Ulum Sakatiga. Pondok mendidik santri dengan penuh kasih sayang, membekali dengan tahfidz, tahsin bersanad, bahasa Arab-Inggris, serta ilmu pengetahuan umum. Lingkungan asrama islami dan terjaga.', NULL, 'publish', '2026-09-14 08:27:46', '2026-09-14 08:27:46'),
(11, 1, 'H. Ahmad Fauzi (Wali Santri MARU)', 'Wali Santri MARU', 'Alhamdulillah, ananda mengalami perubahan karakter yang luar biasa sejak menempuh pendidikan di Madrasah Aliyah Raudhatul Ulum. Ibadahnya tertib, adabnya santun, dan hafalannya terus bertambah.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:09:52', '2026-09-20 14:09:52'),
(12, 1, 'Muhammad Syakir, S.T. (Alumni MARU)', 'Alumni MARU & Profesional', 'Fondasi kedisiplinan, bahasa asing, dan pemahaman agama yang saya dapatkan di Madrasah Aliyah Raudhatul Ulum menjadi modal berharga dalam meniti karier profesional.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:09:52', '2026-09-20 14:09:52'),
(13, 2, 'H. Ahmad Fauzi (Wali Santri MATSARU)', 'Wali Santri MATSARU', 'Alhamdulillah, ananda mengalami perubahan karakter yang luar biasa sejak menempuh pendidikan di Madrasah Tsanawiyah Raudhatul Ulum. Ibadahnya tertib, adabnya santun, dan hafalannya terus bertambah.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:17:33', '2026-09-20 14:17:33'),
(14, 2, 'Muhammad Syakir, S.T. (Alumni MATSARU)', 'Alumni MATSARU & Profesional', 'Fondasi kedisiplinan, bahasa asing, dan pemahaman agama yang saya dapatkan di Madrasah Tsanawiyah Raudhatul Ulum menjadi modal berharga dalam meniti karier profesional.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:17:33', '2026-09-20 14:17:33'),
(15, 3, 'H. Ahmad Fauzi (Wali Santri MIRU)', 'Wali Santri MIRU', 'Alhamdulillah, ananda mengalami perubahan karakter yang luar biasa sejak menempuh pendidikan di Madrasah Ibtidaiyah Raudhatul Ulum. Ibadahnya tertib, adabnya santun, dan hafalannya terus bertambah.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:17:33', '2026-09-20 14:17:33'),
(16, 3, 'Muhammad Syakir, S.T. (Alumni MIRU)', 'Alumni MIRU & Profesional', 'Fondasi kedisiplinan, bahasa asing, dan pemahaman agama yang saya dapatkan di Madrasah Ibtidaiyah Raudhatul Ulum menjadi modal berharga dalam meniti karier profesional.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:17:33', '2026-09-20 14:17:33'),
(17, 4, 'H. Ahmad Fauzi (Wali Santri MATQULARU)', 'Wali Santri MATQULARU', 'Alhamdulillah, ananda mengalami perubahan karakter yang luar biasa sejak menempuh pendidikan di Madrasah Tahfizhul Qur\'an Lil Aulad. Ibadahnya tertib, adabnya santun, dan hafalannya terus bertambah.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:17:34', '2026-09-20 14:17:34'),
(18, 4, 'Muhammad Syakir, S.T. (Alumni MATQULARU)', 'Alumni MATQULARU & Profesional', 'Fondasi kedisiplinan, bahasa asing, dan pemahaman agama yang saya dapatkan di Madrasah Tahfizhul Qur\'an Lil Aulad menjadi modal berharga dalam meniti karier profesional.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:17:34', '2026-09-20 14:17:34'),
(19, 5, 'H. Ahmad Fauzi (Wali Santri TAKIRU)', 'Wali Santri TAKIRU', 'Alhamdulillah, ananda mengalami perubahan karakter yang luar biasa sejak menempuh pendidikan di Taman Kanak-Kanak Islam Raudhatul Ulum. Ibadahnya tertib, adabnya santun, dan hafalannya terus bertambah.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:17:34', '2026-09-20 14:17:34'),
(20, 5, 'Muhammad Syakir, S.T. (Alumni TAKIRU)', 'Alumni TAKIRU & Profesional', 'Fondasi kedisiplinan, bahasa asing, dan pemahaman agama yang saya dapatkan di Taman Kanak-Kanak Islam Raudhatul Ulum menjadi modal berharga dalam meniti karier profesional.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:17:34', '2026-09-20 14:17:34'),
(21, 6, 'H. Ahmad Fauzi (Wali Santri SMPIT RU)', 'Wali Santri SMPIT RU', 'Alhamdulillah, ananda mengalami perubahan karakter yang luar biasa sejak menempuh pendidikan di SMP Islam Terpadu Raudhatul Ulum. Ibadahnya tertib, adabnya santun, dan hafalannya terus bertambah.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:17:34', '2026-09-20 14:17:34'),
(22, 6, 'Muhammad Syakir, S.T. (Alumni SMPIT RU)', 'Alumni SMPIT RU & Profesional', 'Fondasi kedisiplinan, bahasa asing, dan pemahaman agama yang saya dapatkan di SMP Islam Terpadu Raudhatul Ulum menjadi modal berharga dalam meniti karier profesional.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:17:34', '2026-09-20 14:17:34'),
(23, 7, 'H. Ahmad Fauzi (Wali Santri SMAIT RU)', 'Wali Santri SMAIT RU', 'Alhamdulillah, ananda mengalami perubahan karakter yang luar biasa sejak menempuh pendidikan di SMA Islam Terpadu Raudhatul Ulum. Ibadahnya tertib, adabnya santun, dan hafalannya terus bertambah.', '/uploads/avatar-neutral-gray.svg', 'publish', '2026-09-20 14:17:34', '2026-09-20 14:17:34'),
